            if nx[1] < at {
                nx[1] = first_bit(&t8, at).unwrap_or(n);
            }
            if nx[1] < p {
                p = nx[1];
                k = 1;
            }
            // `d1`
            if nx[2] < at {
                nx[2] = first_bit(&t9, at).unwrap_or(n);
            }
            if nx[2] < p {
                p = nx[2];
                k = 2;
            }
            // `s3`
            if nx[3] < at {
                nx[3] = first_bit(&t10, at).unwrap_or(n);
            }
            if nx[3] < p {
                p = nx[3];
                k = 3;
            }
            // `d3`
            if nx[4] < at {
                nx[4] = first_bit(&t11, at).unwrap_or(n);
            }
            if nx[4] < p {
                p = nx[4];
                k = 4;
            }
