            if nx[5] < at {
                nx[5] = first_bit(&t12, at).unwrap_or(n);
            }
            if nx[5] < p {
                p = nx[5];
                k = 5;
            }
            // `fd1`
            if nx[6] < at {
                nx[6] = first_bit(&t14, at).unwrap_or(n);
            }
            if nx[6] < p {
                p = nx[6];
                k = 6;
            }
            // `fs3`
            if nx[7] < at {
                nx[7] = first_bit(&t16, at).unwrap_or(n);
            }
            if nx[7] < p {
                p = nx[7];
                k = 7;
            }
            // `fd3`
